entities.code:
def colorize(
    self,
    message: str,
    bg: Optional[LogColor] = None,
    fg: Optional[LogColor] = None,
    bold: bool = False,
) -> str:
    params = []
    if bg in COLORS:
        params.append(str(COLORS.index(bg) + 40))
    if fg in COLORS:
        params.append(str(COLORS.index(fg) + 30))
    if bold:
        params.append("1")
    if params:
        message = "".join(
            (self.csi, ";".join(params), "m", message, self.reset)
        )
    return message

def deserialize(self, value):
    value = decode(value)
    validators.validate_choice(value.lower(), log.COLORS)
    return value.lower()

def serialize(self, value, display=False):
    lookup = {v: k for k, v in self.levels.items()}
    if value in lookup:
        return encode(lookup[value])
    return ""
